(6412661, 950905, 131284, '<td valign="top">It''s a nice picture, but I''ve seen so many of these on this website it feels pretty uninspired, so I felt I had to deducted a point for that, sorry. I''d probably prefer this picture with a slightly larger dof too so that the foreground flowers all look a bit sharper.</td>', 'It''s a nice picture, but I''ve seen so many of these on this website it feels pretty uninspired, so I felt I had to deducted a point for that, sorry. I''d probably prefer this picture with a slightly larger dof too so that the foreground flowers all look a bit sharper.', '2011-05-13 11:28:35.000000', NULL, 1),
(6412664, 949803, 131284, '<td valign="top">Image is a little too processed for me, perhaps it''s on purpose but it''s quite hard for me to discern what''s happening and so I don''t know how the title relates - is this perhaps the view from under a child''s bed?</td>', 'Image is a little too processed for me, perhaps it''s on purpose but it''s quite hard for me to discern what''s happening and so I don''t know how the title relates - is this perhaps the view from under a child''s bed?', '2011-05-13 11:32:36.000000', NULL, 1),
(6412681, 950097, 131284, '<td valign="top">This gets a 7 from me, simple but nice image, great plant and viewpoint.</td>', 'This gets a 7 from me, simple but nice image, great plant and viewpoint.', '2011-05-13 11:44:06.000000', NULL, 1),
(6412710, 950920, 131284, '<td valign="top">Nice Framing and location.</td>', 'Nice Framing and location.', '2011-05-13 11:57:59.000000', NULL, 1),
(6412714, 950998, 131284, '<td valign="top">Hah, great image, just feels like it''s missing some poorly spelt text in the bottom of the frame. Unfortunately I don''t feel the pov is overly unique though, which is what this challenge is all about, otherwise I''d have scored you higher...<br/> <br/>You can haz 6.</td>', 'Hah, great image, just feels like it''s missing some poorly spelt text in the bottom of the frame. Unfortunately I don''t feel the pov is overly unique though, which is what this challenge is all about, otherwise I''d have scored you higher... You can haz 6.', '2011-05-13 12:02:02.000000', NULL, 1),
(6412720, 950836, 131284, '<td valign="top">Funnily enough I had a very similar image I considered for this challenge. I quite like it but actually find the blur on the left rather distracting, would have liked something a little smoother.</td>', 'Funnily enough I had a very similar image I considered for this challenge. I quite like it but actually find the blur on the left rather distracting, would have liked something a little smoother.', '2011-05-13 12:04:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6412722, 950790, 131284, '<td valign="top">I like the image, on it''s own one of the better entries, but I''ve seen so many of these on this site it feels pretty uninspired so felt I had to dock a mark for that, sorry.</td>', 'I like the image, on it''s own one of the better entries, but I''ve seen so many of these on this site it feels pretty uninspired so felt I had to dock a mark for that, sorry.', '2011-05-13 12:06:54.000000', NULL, 1),
(6412725, 950433, 131284, '<td valign="top">Love the location, I''m sure there are lots of great photo''s to be had round there, so while I like the image a lot also I feel it''s a shame the pov isn''t a bit more unique, which is the purpose of this challenge.<br/> <br/>I gave you a 6 but I''m sure there are many unique points of view in that location that would make great photos and I''d have scored higher for.</td>', 'Love the location, I''m sure there are lots of great photo''s to be had round there, so while I like the image a lot also I feel it''s a shame the pov isn''t a bit more unique, which is the purpose of this challenge. I gave you a 6 but I''m sure there are many unique points of view in that location that would make great photos and I''d have scored higher for.', '2011-05-13 12:10:22.000000', NULL, 1),
(6412729, 949950, 131284, '<td valign="top">The photo''s not bad, but I don''t feel the pov is overly unique - just a little bit closer than we normally view a bowl of strawberries.</td>', 'The photo''s not bad, but I don''t feel the pov is overly unique - just a little bit closer than we normally view a bowl of strawberries.', '2011-05-13 12:12:11.000000', NULL, 1),
(6412733, 950990, 131284, '<td valign="top">Image is okay, though while I may be missing something I don''t see how it is or represents a unique point of view, sorry.</td>', 'Image is okay, though while I may be missing something I don''t see how it is or represents a unique point of view, sorry.', '2011-05-13 12:14:55.000000', NULL, 1),
(6412735, 950966, 131284, '<td valign="top">I''d like the image a little sharper but it''s still quite nice. I don''t really consider a crop of a giraffes head a unique point of view though, sorry.</td>', 'I''d like the image a little sharper but it''s still quite nice. I don''t really consider a crop of a giraffes head a unique point of view though, sorry.', '2011-05-13 12:16:21.000000', NULL, 1),
(6412739, 950010, 131284, '<td valign="top">Not a bad image, would have liked a little sharper focus on the left hand though. Also, while this is a "unique point of view", looking down a guitars neck on to someone''s hands is an image I''ve seen many time so wasn''t really "unique" enough for me, sorry. Gave it a 5.</td>', 'Not a bad image, would have liked a little sharper focus on the left hand though. Also, while this is a "unique point of view", looking down a guitars neck on to someone''s hands is an image I''ve seen many time so wasn''t really "unique" enough for me, sorry. Gave it a 5.', '2011-05-13 12:18:58.000000', NULL, 1),
(6412741, 950926, 131284, '<td valign="top">I like this picture, nice dof and framing. Unfortunately, while I respect the idea, for me a challenge to produce a unique pov should be a little more unique than this.</td>', 'I like this picture, nice dof and framing. Unfortunately, while I respect the idea, for me a challenge to produce a unique pov should be a little more unique than this.', '2011-05-13 12:22:34.000000', NULL, 1),
(6412747, 950465, 131284, '<td valign="top">Just like the other two similar images in this challenge, the picture itself is quite nice and the point of view in many ways unique - however there are so many of these very-similar images on this site already I just feel it''s pretty uninspired and have to deduct points that that, sorry - 6.</td>', 'Just like the other two similar images in this challenge, the picture itself is quite nice and the point of view in many ways unique - however there are so many of these very-similar images on this site already I just feel it''s pretty uninspired and have to deduct points that that, sorry - 6.', '2011-05-13 12:27:43.000000', NULL, 1),
(6412750, 950716, 131284, '<td valign="top">Love the pov and framing. Also the girl looks a lot like a young version of a close friend of mine - don''t think it would be fair to give a higher score for that, but makes me like the image more =).</td>', 'Love the pov and framing. Also the girl looks a lot like a young version of a close friend of mine - don''t think it would be fair to give a higher score for that, but makes me like the image more =).', '2011-05-13 12:32:31.000000', NULL, 1),
