(6412752, 950996, 131284, '<td valign="top">Not a fan of the border, but nice image - if anything maybe a little too saturated for my taste, but I still like it.</td>', 'Not a fan of the border, but nice image - if anything maybe a little too saturated for my taste, but I still like it.', '2011-05-13 12:34:24.000000', NULL, 1),
(6412753, 950983, 131284, '<td valign="top">Love it, just not keen on the bright white backdrop/sky.</td>', 'Love it, just not keen on the bright white backdrop/sky.', '2011-05-13 12:34:26.000000', NULL, 1),
(6412754, 950655, 131284, '<td valign="top">Little too green for my taste and don''t really feel the pov is particularly unique, but still nice image.</td>', 'Little too green for my taste and don''t really feel the pov is particularly unique, but still nice image.', '2011-05-13 12:34:31.000000', NULL, 1),
